    "share.linkFold": "Fills in their sign-in on this Hub",
    "share.moreTitle": "QR code and agent prompt",
    "share.moreFold": "Other ways to hand it over",
    "share.linkLabel": "Sign-in link · shown once",
    "share.linkNote": "Opening it fills in their sign-in on this Hub. They see what it opens and press Open themselves.",
    "share.linkCopy": "Copy the link",
    "share.qrLinkLabel": "QR code with the sign-in link",
