    "share.promptHead": 'You can use my Hoody realm "{{realm}}" through the Hoody API. Work only in this realm.',
    "share.promptApi": "API base URL: {{url}}",
    "share.promptAuth": "Send this header with every request: Authorization: Bearer {{token}}",
    "share.promptEnds": "This access ends {{date}}.",
    "share.promptPlaceholder": "<paste the token you were sent>",
    "share.promptCopy": "Copy the prompt",
